  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. No agent is auto-selected — the user stays on the new-agent
 18→ *    creation screen until they explicitly pick or spawn an agent.
 19→ *
 20→ * ## Lazy history loading
 21→ *
 22→ * Message histories are loaded on demand. When `activeAgentId` changes
 23→ * and the agent hasn't been loaded yet, the hook sends
 24→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 25→ * When the server responds with `message_history`, the agent's messages
 26→ * are populated and `historyLoading` becomes false.
 27→ *
 28→ * The `loadedAgents` Set tracks which agents have been fetched so that
 29→ * switching back to a previously viewed agent is instant.
 30→ *
 31→ * ## Resilience features
 32→ *
 33→ * - Handles `message_history` replay from server on demand.
 34→ * - Handles `cli_disconnected` / `cli_connected` events.
 35→ * - Deduplicates messages using a per-agent processed count.
 36→ * - Robust reconnection guard (clears previous timer before scheduling).
 37→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 38→ *
 39→ * ## Logging
 40→ *
 41→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 42→ * in the browser console to debug connection and message delivery issues.
 43→ */
 44→
 45→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 46→import type {
 47→  AgentInfo,
 48→  AgentStatus,
 49→  ChatMessage,
 50→  ClaudeAssistant,
 51→  ClaudeControlRequest,
 52→  ClaudeMessage,
 53→  ClaudeResult,
 54→  ClaudeSystemInit,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
 64→} from "@/lib/types";
 65→
 66→/** Connect to the WS server on the same host the page was loaded from. */
 67→const WS_URL =
 68→  typeof window !== "undefined"
 69→    ? `ws://${window.location.hostname}:9900/browser`
 70→    : "ws://localhost:9900/browser";
 71→
 72→/** Per-agent client state. */
 73→export interface AgentClientState {
 74→  status: AgentStatus;
 75→  messages: ChatMessage[];
 76→  /** Raw Claude NDJSON messages for debug view. */
 77→  rawMessages: ClaudeMessage[];
 78→  label: string;
 79→  tmuxSession: string | null;
 80→  createdAt: number;
 81→}
 82→
 83→/**
 84→ * Extract displayable text from a Claude assistant message.
 85→ * Content blocks may be text, tool_use, or tool_result — each is
 86→ * handled defensively since the array structure can vary.
 87→ */
 88→function extractText(msg: ClaudeAssistant): string {
 89→  const blocks = msg.message?.content;
 90→  if (!blocks || !Array.isArray(blocks)) return "";
 91→  return blocks
 92→    .map((b) => {
 93→      if (b.type === "text") return b.text;
 94→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 95→      if (b.type === "tool_result") {
 96→        const c = (b as { content?: unknown }).content;
 97→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
 98→      }
 99→      return "";
100→    })
101→    .filter(Boolean)
102→    .join("\n");
103→}
104→
105→/** Module-level counter for generating unique message IDs. */
106→let msgCounter = 0;
107→function nextId() {
108→  return `msg-${Date.now()}-${++msgCounter}`;
109→}
110→
111→/**
112→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
113→ * Used both for live messages and for replaying message_history.
114→ */
115→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
116→  if (relayMsg.type === "relay") {
117→    const msg = relayMsg.message;
118→
119→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
120→      const init = msg as ClaudeSystemInit;
121→      return {
122→        id: nextId(),
123→        role: "system",
124→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
125→        timestamp: Date.now(),
126→      };
127→    }
128→
129→    if (msg.type === "user") {
130→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
131→      // Only render human-typed user messages (string content).
132→      // CLI tool_result messages have array content — these are internal
133→      // protocol messages and are only visible in the raw message viewer.
134→      if (typeof rawContent !== "string") return null;
135→      if (!rawContent.trim()) return null;
136→      return {
137→        id: nextId(),
138→        role: "user",
139→        content: rawContent,
140→        timestamp: Date.now(),
141→      };
142→    }
143→
144→    if (msg.type === "assistant") {
145→      const assistant = msg as ClaudeAssistant;
146→      const text = extractText(assistant);
147→      if (!text) return null;
148→
149→      const blocks = assistant.message?.content ?? [];
150→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
151→      const toolCalls: ToolCallInfo[] = blocks
152→        .filter((b) => b.type === "tool_use")
153→        .map((b) => ({
154→          name: (b as { name: string }).name,
155→          toolUseId: (b as { id: string }).id,
156→        }));
157→      const isToolOnly = !hasText && toolCalls.length > 0;
158→
159→      return {
160→        id: nextId(),
161→        role: "assistant",
162→        content: text,
163→        timestamp: Date.now(),
164→        toolCalls,
165→        isToolOnly,
166→      };
167→    }
168→
169→    if (msg.type === "result") {
170→      const result = msg as ClaudeResult;
171→      const cost = result.total_cost_usd ?? result.cost_usd ?? 0;
172→      const summary = result.is_error
173→        ? `Error: ${result.error}`
174→        : `Done — ${result.num_turns ?? "?"} turns, $${cost.toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
175→      return {
176→        id: nextId(),
177→        role: "system",
178→        content: summary,
179→        timestamp: Date.now(),
180→      };
181→    }
182→
183→    if (msg.type === "control_request") {
184→      const cr = msg as ClaudeControlRequest;
185→
186→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
187→      if (cr.request.tool_name === "AskUserQuestion") {
188→        const input = cr.request.input as { questions?: UserQuestion[] };
189→        const questions = Array.isArray(input.questions) ? input.questions : [];
190→        return {
191→          id: nextId(),
192→          role: "system",
193→          content: "Question from Claude",
194→          timestamp: Date.now(),
195→          userQuestion: {
196→            requestId: cr.request_id,
197→            questions,
198→          },
199→        };
200→      }
201→
202→      return {
203→        id: nextId(),
204→        role: "system",
205→        content: `Tool approval requested: ${cr.request.tool_name}`,
206→        timestamp: Date.now(),
207→        controlRequest: {
208→          id: cr.request_id,
209→          tool_name: cr.request.tool_name,
210→          input: cr.request.input,
211→          description: cr.request.description,
212→        },
213→      };
214→    }
215→  }
216→
217→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
218→    return {
219→      id: nextId(),
220→      role: "system",
221→      content: `Error: ${relayMsg.error}`,
222→      timestamp: Date.now(),
223→    };
224→  }
225→
226→  return null;
227→}
228→
229→/** Console logger with [thos] prefix for easy filtering. */
230→function log(...args: unknown[]) {
231→  console.log("[thos-ws]", ...args);
232→}
233→
234→export function useWebSocket() {
235→  const wsRef = useRef<WebSocket | null>(null);
236→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
237→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
238→  const closingRef = useRef(false);
239→  const [connected, setConnected] = useState(false);
240→  /** True once we've received the initial agent_list from the server. */
241→  const [initialLoadDone, setInitialLoadDone] = useState(false);
242→
243→  // Multi-agent state
244→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
245→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
246→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
247→
248→  // Task state
249→  const [tasks, setTasks] = useState<Task[]>([]);
250→
251→  // Per-agent deduplication: track count of processed messages per agent
252→  // to avoid duplicating messages already in local state during history replay.
253→  const processedCountRef = useRef<Map<string, number>>(new Map());
254→
255→  // Track which agents have had their history loaded (lazy loading).
256→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
257→
258→  /** Immutably update a single agent's state in the Map. */
259→  const updateAgent = useCallback(
260→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
261→      setAgents((prev) => {
262→        const existing = prev.get(agentId);
263→        if (!existing) return prev;
264→        const next = new Map(prev);
265→        next.set(agentId, updater(existing));
266→        return next;
267→      });
268→    },
269→    []
270→  );
271→
272→  const connect = useCallback(() => {
273→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
274→    if (wsRef.current) {
275→      wsRef.current.close();
276→      wsRef.current = null;
277→    }
278→
279→    // Reset dedup counts on new connection — server will send fresh history
280→    processedCountRef.current.clear();
281→    setInitialLoadDone(false);
282→    setLoadedAgents(new Set());
283→
284→    log("connecting to", WS_URL);
285→    const ws = new WebSocket(WS_URL);
286→    wsRef.current = ws;
287→
288→    ws.onopen = () => {
289→      log("connected");
290→      setConnected(true);
291→    };
292→
293→    ws.onclose = () => {
294→      log("disconnected, closingRef =", closingRef.current);
295→      setConnected(false);
296→      wsRef.current = null;
297→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
298→      if (closingRef.current) return;
299→      // Reconnection guard: clear any existing timer before scheduling
300→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
301→      log("scheduling reconnect in 2s");
302→      reconnectTimer.current = setTimeout(() => connect(), 2000);
303→    };
304→
305→    ws.onerror = (e) => {
306→      log("error", e);
307→      // onclose will fire after onerror, which triggers reconnect
308→    };
309→
310→    ws.onmessage = (event) => {
311→      let data: ServerMessage;
312→      try {
313→        data = JSON.parse(event.data as string);
314→      } catch {
315→        return;
316→      }
317→
318→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
319→
320→      // ── task_list: full task list from server ──
321→      if (data.type === "task_list") {
322→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
323→        setTasks((data as ServerTaskList).tasks);
324→        return;
325→      }
326→
327→      // ── task_updated: single task changed ──
328→      if (data.type === "task_updated") {
329→        const updated = (data as ServerTaskUpdated).task;
330→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
331→        return;
332→      }
333→
334→      // ── task_deleted: remove task ──
335→      if (data.type === "task_deleted") {
336→        const deletedId = (data as ServerTaskDeleted).taskId;
337→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
338→        return;
339→      }
340→
341→      // ── message_history: replay full history from server ──
342→      if (data.type === "message_history") {
343→        const historyMsg = data as ServerMessageHistory;
344→        const agentId = historyMsg.agentId;
345→        const serverMessages = historyMsg.messages;
346→        log("message_history:", agentId, serverMessages.length, "raw msgs");
347→
348→        // Convert all server messages to ChatMessages + extract raw Claude messages
349→        const chatMessages: ChatMessage[] = [];
350→        const rawMessages: ClaudeMessage[] = [];
351→        for (const sm of serverMessages) {
352→          if (sm.type === "relay") {
353→            rawMessages.push(sm.message);
354→          }
355→          const cm = relayChatMessage(agentId, sm);
356→          if (cm) chatMessages.push(cm);
357→        }
358→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
359→
360→        // Always replace local messages with server history (source of truth).
361→        setAgents((prev) => {
362→          const existing = prev.get(agentId);
363→          if (!existing) {
364→            log("message_history:", agentId, "agent not in map yet, creating");
365→            const next = new Map(prev);
366→            next.set(agentId, {
367→              status: "idle",
368→              messages: chatMessages,
369→              rawMessages,
370→              label: "",
371→              tmuxSession: null,
372→              createdAt: 0,
373→            });
374→            return next;
375→          }
376→          const next = new Map(prev);
377→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
378→          return next;
379→        });
380→
381→        processedCountRef.current.set(agentId, chatMessages.length);
382→        setLoadedAgents((prev) => {
383→          if (prev.has(agentId)) return prev;
384→          const next = new Set(prev);
385→          next.add(agentId);
386→          return next;
387→        });
388→        return;
389→      }
390→
391→      // ── history_cleared: wipe local messages for this agent ──
392→      if (data.type === "history_cleared") {
393→        updateAgent(data.agentId, (prev) => ({
394→          ...prev,
395→          messages: [],
396→          rawMessages: [],
397→        }));
398→        processedCountRef.current.set(data.agentId, 0);
399→        return;
400→      }
401→
402→      // ── cli_disconnected: show system message ──
403→      if (data.type === "cli_disconnected") {
404→        updateAgent(data.agentId, (prev) => ({
405→          ...prev,
406→          messages: [
407→            ...prev.messages,
408→            {
409→              id: nextId(),
410→              role: "system",
411→              content: "CLI session ended",
412→              timestamp: Date.now(),
413→            },
414→          ],
415→        }));
416→        return;
417→      }
418→
419→      // ── cli_connected: show system message ──
420→      if (data.type === "cli_connected") {
421→        updateAgent(data.agentId, (prev) => {
422→          const isReconnect = prev.messages.length > 0;
423→          return {
424→            ...prev,
425→            messages: [
426→              ...prev.messages,
427→              {
428→                id: nextId(),
429→                role: "system",
430→                content: isReconnect ? "CLI reconnected" : "CLI connected",
431→                timestamp: Date.now(),
432→              },
433→            ],
434→          };
435→        });
436→        return;
437→      }
438→
439→      // ── agent_list: reconcile sidebar state from server ──
440→      if (data.type === "agent_list") {
441→        const serverAgents = data.agents as AgentInfo[];
442→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
443→        setAgents((prev) => {
444→          const next = new Map(prev);
445→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
446→
447→          // Update or add agents from server
448→          for (const info of serverAgents) {
449→            const existing = next.get(info.agentId);
450→            if (existing) {
451→              next.set(info.agentId, {
452→                ...existing,
453→                status: info.status,
454→                tmuxSession: info.tmuxSession,
455→                label: info.label,
456→              });
457→            } else {
458→              next.set(info.agentId, {
459→                status: info.status,
460→                messages: [],
461→                rawMessages: [],
462→                label: info.label,
463→                tmuxSession: info.tmuxSession,
464→                createdAt: info.createdAt,
465→              });
466→            }
467→          }
468→
469→          // Remove agents no longer on the server
470→          for (const id of next.keys()) {
471→            if (!serverIds.has(id)) {
472→              next.delete(id);
473→            }
474→          }
475→
476→          return next;
477→        });
478→        setAgentOrder(serverAgents.map((a) => a.agentId));
479→        setInitialLoadDone(true);
480→
481→        // No auto-select: leave user on the new-agent creation screen
482→        // until they explicitly pick an agent or spawn a new one.
483→        return;
484→      }
485→
486→      // ── spawned: auto-select the newly created agent ──
487→      if (data.type === "spawned") {
488→        setActiveAgentId(data.agentId);
489→        return;
490→      }
491→
492→      // ── status: update a specific agent's status ──
493→      if (data.type === "status") {
494→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
495→        return;
496→      }
497→
498→      // ── error: append to agent's message list ──
499→      if (data.type === "error") {
500→        updateAgent(data.agentId, (prev) => ({
501→          ...prev,
502→          messages: [
503→            ...prev.messages,
504→            {
505→              id: nextId(),
506→              role: "system",
507→              content: `Error: ${data.error}`,
508→              timestamp: Date.now(),
509→            },
510→          ],
511→        }));
512→        // Track processed count for dedup
513→        processedCountRef.current.set(
514→          data.agentId,
515→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
516→        );
517→        return;
518→      }
519→
520→      // ── relay: append claude message to agent's history ──
521→      if (data.type === "relay") {
522→        const agentId = data.agentId;
523→        const rawMsg = data.message;
524→        const chatMsg = relayChatMessage(agentId, data);
525→
526→        updateAgent(agentId, (prev) => ({
527→          ...prev,
528→          rawMessages: [...prev.rawMessages, rawMsg],
529→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
530→        }));
531→        if (chatMsg) {
532→          // Track processed count for dedup
533→          processedCountRef.current.set(
534→            agentId,
535→            (processedCountRef.current.get(agentId) ?? 0) + 1
536→          );
537→        }
538→        return;
539→      }
540→    };
541→  }, [updateAgent]);
542→
543→  useEffect(() => {
544→    closingRef.current = false;
545→    connect();
546→    return () => {
547→      closingRef.current = true;
548→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
549→      wsRef.current?.close();
550→    };
551→  }, [connect]);
552→
553→  const send = useCallback((data: object) => {
554→    if (wsRef.current?.readyState === WebSocket.OPEN) {
555→      wsRef.current.send(JSON.stringify(data));
556→    }
557→  }, []);
558→
559→  // Request history for the active agent if not already loaded.
560→  useEffect(() => {
561→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
562→    log("requesting history for", activeAgentId);
563→    send({ type: "request_history", agentId: activeAgentId });
564→  }, [activeAgentId, loadedAgents, send]);
565→
566→  const spawnAgent = useCallback(
567→    (prompt: string) => {
568→      send({ type: "spawn", prompt });
569→    },
570→    [send]
571→  );
572→
573→  const sendMessage = useCallback(
574→    (content: string) => {
575→      if (!activeAgentId) return;
576→      // Optimistically add user message to local state
577→      updateAgent(activeAgentId, (prev) => ({
578→        ...prev,
579→        messages: [
580→          ...prev.messages,
581→          {
582→            id: nextId(),
583→            role: "user",
584→            content,
585→            timestamp: Date.now(),
586→          },
587→        ],
588→      }));
589→      send({ type: "send_message", agentId: activeAgentId, content });
590→    },
591→    [send, activeAgentId, updateAgent]
592→  );
593→
594→  const respondToControl = useCallback(
595→    (requestId: string, allow: boolean) => {
596→      if (!activeAgentId) return;
597→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
598→      updateAgent(activeAgentId, (prev) => ({
599→        ...prev,
600→        messages: prev.messages.map((m) =>
601→          m.controlRequest?.id === requestId
602→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
603→            : m
604→        ),
605→      }));
606→    },
607→    [send, activeAgentId, updateAgent]
608→  );
609→
610→  /** Respond to an AskUserQuestion control request with the user's selections. */
611→  const respondToUserQuestion = useCallback(
612→    (requestId: string, answers: Record<string, string>) => {
613→      if (!activeAgentId) return;
614→      send({
615→        type: "control_response",
616→        agentId: activeAgentId,
617→        request_id: requestId,
618→        allow: true,
619→        answers,
620→      });
621→      updateAgent(activeAgentId, (prev) => ({
622→        ...prev,
623→        messages: prev.messages.map((m) =>
624→          m.userQuestion?.requestId === requestId
625→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
626→            : m
627→        ),
628→      }));
629→    },
630→    [send, activeAgentId, updateAgent]
631→  );
632→
633→  // ── Agent management actions ──────────────────────────────────────────────
634→
635→  const killAgent = useCallback(
636→    (agentId: string) => {
637→      send({ type: "kill_agent", agentId });
638→    },
639→    [send]
640→  );
641→
642→  const deleteAgent = useCallback(
643→    (agentId: string) => {
644→      send({ type: "delete_agent", agentId });
645→      // Deselect if we just deleted the active agent
646→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
647→    },
648→    [send]
649→  );
650→
651→  const renameAgent = useCallback(
652→    (agentId: string, label: string) => {
653→      send({ type: "rename_agent", agentId, label });
654→    },
655→    [send]
656→  );
657→
658→  const clearHistory = useCallback(
659→    (agentId: string) => {
660→      send({ type: "clear_history", agentId });
661→    },
662→    [send]
663→  );
664→
665→  // ── Task actions ──────────────────────────────────────────────────────────
666→
667→  const createTask = useCallback(
668→    (title: string, description: string, priority: TaskPriority) => {
669→      send({ type: "create_task", title, description, priority });
670→    },
671→    [send]
672→  );
673→
674→  const updateTask = useCallback(
675→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
