  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 20→import { condenseMessages } from "@/lib/condense-messages";
 21→import { StatusBar } from "./status-bar";
 22→import { AgentSummary } from "./agent-summary";
 23→import { Message } from "./message";
 24→import { ControlRequest } from "./control-request";
 25→import { UserQuestion } from "./user-question";
 26→import { CondensedToolGroup } from "./condensed-tool-group";
 27→import { Button } from "@/components/ui/button";
 28→import { Terminal, MessageSquare, ListTodo } from "lucide-react";
 29→
 30→export function Chat({
 31→  connected,
 32→  loading,
 33→  status,
 34→  messages,
 35→  rawMessages,
 36→  onSendMessage,
 37→  onSpawnAgent,
 38→  onRespondToControl,
 39→  onRespondToUserQuestion,
 40→  showTasks,
 41→  onToggleTasks,
 42→  onToggleSidebar,
 43→}: {
 44→  connected: boolean;
 45→  loading?: boolean;
 46→  status: AgentStatus;
 47→  messages: ChatMessage[];
 48→  rawMessages: ClaudeMessage[];
 49→  onSendMessage: (content: string) => void;
 50→  onSpawnAgent: (prompt: string) => void;
 51→  onRespondToControl: (requestId: string, allow: boolean) => void;
 52→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 53→  showTasks?: boolean;
 54→  onToggleTasks?: () => void;
 55→  onToggleSidebar?: () => void;
 56→}) {
 57→  const [input, setInput] = useState("");
 58→  const [showRaw, setShowRaw] = useState(false);
 59→  const scrollRef = useRef<HTMLDivElement>(null);
 60→
 61→  useEffect(() => {
 62→    scrollRef.current?.scrollTo({
 63→      top: scrollRef.current.scrollHeight,
 64→      behavior: "smooth",
 65→    });
 66→  }, [messages, rawMessages, showRaw]);
 67→
 68→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 69→  const isActive = status === "connected" || status === "thinking";
 70→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 71→
 72→  function handleSubmit(e: React.FormEvent) {
 73→    e.preventDefault();
 74→    const trimmed = input.trim();
 75→    if (!trimmed) return;
 76→
 77→    if (isActive) {
 78→      onSendMessage(trimmed);
 79→    } else {
 80→      onSpawnAgent(trimmed);
 81→    }
 82→    setInput("");
 83→  }
 84→
 85→  return (
 86→    <div className="flex h-full flex-col">
 87→      <StatusBar
 88→        connected={connected}
 89→        status={status}
 90→        showRaw={showRaw}
 91→        onToggleRaw={() => setShowRaw((v) => !v)}
 92→        showTasks={showTasks}
 93→        onToggleTasks={onToggleTasks}
 94→        onToggleSidebar={onToggleSidebar}
 95→      />
 96→      <AgentSummary rawMessages={rawMessages} />
 97→
 98→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
 99→        {loading ? (
100→          <div className="flex h-full flex-col items-center justify-center gap-3">
101→            <div className="flex gap-1">
102→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
103→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
104→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
105→            </div>
106→            <span className="text-xs text-muted-foreground">
107→              {connected ? "Loading messages..." : "Connecting..."}
108→            </span>
109→          </div>
110→        ) : showRaw ? (
111→          rawMessages.length === 0 ? (
112→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
113→              No raw messages yet
114→            </div>
115→          ) : (
116→            <div className="space-y-1">
117→              {rawMessages.map((msg, i) => (
118→                <RawMessage key={i} message={msg} index={i} />
119→              ))}
120→            </div>
121→          )
122→        ) : (
123→          <>
124→            {messages.length === 0 && (
125→              <div className="flex h-full items-center justify-center">
126→                <div className="flex max-w-sm flex-col items-center gap-6 text-center">
127→                  <div className="flex size-12 items-center justify-center rounded-xl border bg-muted/50">
128→                    <Terminal className="size-6 text-muted-foreground" />
129→                  </div>
130→                  <div className="space-y-2">
131→                    <h2 className="text-base font-medium">Spawn an agent</h2>
132→                    <p className="text-sm text-muted-foreground">
133→                      Enter a prompt below to start a new Claude Code session. The agent runs in your terminal and streams results here in real time.
134→                    </p>
135→                  </div>
136→                  <div className="w-full space-y-2 text-left text-[13px]">
137→                    <div className="flex items-start gap-3 rounded-lg border px-3 py-2.5">
138→                      <MessageSquare className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
139→                      <div>
140→                        <span className="font-medium">Chat</span>
141→                        <span className="text-muted-foreground"> — send follow-up messages to a running agent</span>
142→                      </div>
143→                    </div>
144→                    <div className="flex items-start gap-3 rounded-lg border px-3 py-2.5">
145→                      <ListTodo className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
146→                      <div>
147→                        <span className="font-medium">Tasks</span>
148→                        <span className="text-muted-foreground"> — create tasks and delegate them to agents</span>
149→                      </div>
150→                    </div>
151→                  </div>
152→                </div>
153→              </div>
154→            )}
155→            {displayItems.map((item) => {
156→              if (item.kind === "condensed") {
157→                return <CondensedToolGroup key={item.id} group={item} />;
158→              }
159→              const msg = item.message;
160→              return msg.userQuestion ? (
161→                <UserQuestion
162→                  key={msg.id}
163→                  message={msg}
164→                  onRespond={onRespondToUserQuestion}
165→                />
166→              ) : msg.controlRequest ? (
167→                <ControlRequest
168→                  key={msg.id}
169→                  message={msg}
170→                  onRespond={onRespondToControl}
171→                />
172→              ) : (
173→                <Message key={msg.id} message={msg} />
174→              );
175→            })}
176→          </>
177→        )}
178→      </div>
179→
180→      {isArchived && messages.length > 0 ? (
181→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
182→          This session has ended
183→        </div>
184→      ) : (
185→        <form
186→          onSubmit={handleSubmit}
187→          className="flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
188→        >
189→          <input
190→            type="text"
191→            value={input}
192→            onChange={(e) => setInput(e.target.value)}
193→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
194→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
195→          />
196→          <Button type="submit" disabled={!connected || !input.trim()}>
197→            {isActive ? "Send" : "Spawn"}
198→          </Button>
199→        </form>
200→      )}
201→    </div>
202→  );
203→}
204→
205→/** Badge color per Claude NDJSON message type. */
206→const TYPE_COLORS: Record<string, string> = {
207→  system: "text-yellow-500",
208→  assistant: "text-blue-400",
209→  result: "text-green-500",
210→  control_request: "text-orange-400",
211→  keep_alive: "text-muted-foreground",
212→};
213→
214→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
215→  const [expanded, setExpanded] = useState(false);
216→  const subtype = (message as { subtype?: string }).subtype;
217→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
218→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
219→
220→  return (
221→    <div className="font-mono text-[11px] leading-relaxed">
222→      <button
223→        onClick={() => setExpanded((v) => !v)}
224→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
225→      >
226→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
227→        <span className={colorClass}>{typeLabel}</span>
228→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
229→      </button>
230→      {expanded && (
231→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
232→          {JSON.stringify(message, null, 2)}
233→        </pre>
234→      )}
235→    </div>
236→  );
237→}
