  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ *
 11→ * ## Key architecture notes
 12→ *
 13→ * - On browser connect, the server sends `agent_list` + `task_list` only.
 14→ * - Message histories are loaded lazily: the browser sends
 15→ *   `request_history` when selecting an agent, and the server responds
 16→ *   with `message_history` for that single agent.
 17→ * - Live messages for active agents are broadcast via `relay` in real time.
 18→ * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 19→ */
 20→
 21→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 22→
 23→/**
 24→ * Sent once after the first user prompt is received. Contains session
 25→ * metadata like the model name, working directory, and available tools.
 26→ */
 27→export interface ClaudeSystemInit {
 28→  type: "system";
 29→  subtype: "init";
 30→  session_id: string;
 31→  tools: unknown[];
 32→  mcp_servers: unknown[];
 33→  model: string;
 34→  cwd: string;
 35→}
 36→
 37→/**
 38→ * An assistant turn. `message.content` is an array of content blocks
 39→ * (text, tool_use, tool_result) that may arrive incrementally — each
 40→ * NDJSON line is a complete snapshot of the message so far.
 41→ */
 42→export interface ClaudeAssistant {
 43→  type: "assistant";
 44→  message: {
 45→    id: string;
 46→    role: "assistant";
 47→    content: AssistantContentBlock[];
 48→    model: string;
 49→    stop_reason: string | null;
 50→  };
 51→  session_id: string;
 52→}
 53→
 54→/** A single content block inside an assistant message. */
 55→export type AssistantContentBlock =
 56→  | { type: "text"; text: string }
 57→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 58→  | { type: "tool_result"; tool_use_id: string; content: string };
 59→
 60→/**
 61→ * Terminal message for a session. Includes cost/duration metrics.
 62→ * `is_error` is true when `subtype` is `"error"`.
 63→ */
 64→export interface ClaudeResult {
 65→  type: "result";
 66→  subtype: "success" | "error";
 67→  result?: string;
 68→  error?: string;
 69→  session_id: string;
 70→  cost_usd?: number;
 71→  total_cost_usd?: number;
 72→  duration_ms: number;
 73→  duration_api_ms: number;
 74→  is_error: boolean;
 75→  num_turns: number;
 76→}
 77→
 78→/**
 79→ * Claude is requesting permission to execute a tool. The dashboard must
 80→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 81→ *
 82→ * Wire format uses a nested `request` object with `request_id` at the
 83→ * top level for correlation (matches Companion protocol docs).
 84→ */
 85→export interface ClaudeControlRequest {
 86→  type: "control_request";
 87→  request_id: string;
 88→  request: {
 89→    subtype: "can_use_tool";
 90→    tool_name: string;
 91→    input: Record<string, unknown>;
 92→    tool_use_id?: string;
 93→    description?: string;
 94→  };
 95→  session_id?: string;
 96→}
 97→
 98→/**
 99→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
100→ * the signal that the CLI is ready to receive the first user prompt.
101→ */
102→export interface ClaudeSystemHook {
103→  type: "system";
104→  subtype: "hook_started" | "hook_response";
105→  session_id?: string;
106→}
107→
108→/** Discriminated union of all known Claude NDJSON message shapes. */
109→export type ClaudeMessage =
110→  | ClaudeSystemInit
111→  | ClaudeAssistant
112→  | ClaudeResult
113→  | ClaudeControlRequest
114→  | ClaudeSystemHook
115→  | { type: string; subtype?: string; [key: string]: unknown };
116→
117→// ── Browser ↔ Server messages ─────────────────────────────────────────────
118→
119→/** Browser asks the server to spawn a new Claude CLI process. */
120→export interface BrowserSpawn {
121→  type: "spawn";
122→  prompt: string;
123→}
124→
125→/** Browser sends a follow-up message to an already-running Claude session. */
126→export interface BrowserSendMessage {
127→  type: "send_message";
128→  agentId: string;
129→  content: string;
130→}
131→
132→/** Browser responds to a tool approval request (allow or deny). */
133→export interface BrowserControlResponse {
134→  type: "control_response";
135→  agentId: string;
136→  request_id: string;
137→  allow: boolean;
138→}
139→
140→/** Browser asks the server to kill a running agent's tmux session + CLI. */
141→export interface BrowserKillAgent {
142→  type: "kill_agent";
143→  agentId: string;
144→}
145→
146→/** Browser asks the server to permanently delete an agent. */
147→export interface BrowserDeleteAgent {
148→  type: "delete_agent";
149→  agentId: string;
150→}
151→
152→/** Browser asks the server to rename an agent. */
153→export interface BrowserRenameAgent {
154→  type: "rename_agent";
155→  agentId: string;
156→  label: string;
157→}
158→
159→/** Browser asks the server to clear an agent's message history. */
160→export interface BrowserClearHistory {
161→  type: "clear_history";
162→  agentId: string;
163→}
164→
165→/** Browser requests message history for a specific agent (lazy loading). */
166→export interface BrowserRequestHistory {
167→  type: "request_history";
168→  agentId: string;
169→}
170→
171→/** Browser asks the server to create a new task. */
172→export interface BrowserCreateTask {
173→  type: "create_task";
174→  title: string;
175→  description: string;
176→  priority: TaskPriority;
177→}
178→
179→/** Browser asks to update a task's fields. */
180→export interface BrowserUpdateTask {
181→  type: "update_task";
182→  taskId: string;
183→  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
184→}
185→
186→/** Browser asks to delete a task. */
187→export interface BrowserDeleteTask {
188→  type: "delete_task";
189→  taskId: string;
190→}
191→
192→/** Browser asks to delegate a task to a new Claude agent. */
193→export interface BrowserDelegateTask {
194→  type: "delegate_task";
195→  taskId: string;
196→}
197→
198→/** Union of all messages the browser can send to the WS server. */
199→export type BrowserMessage =
200→  | BrowserSpawn
201→  | BrowserSendMessage
202→  | BrowserControlResponse
203→  | BrowserKillAgent
204→  | BrowserDeleteAgent
205→  | BrowserRenameAgent
206→  | BrowserClearHistory
207→  | BrowserRequestHistory
208→  | BrowserCreateTask
209→  | BrowserUpdateTask
210→  | BrowserDeleteTask
211→  | BrowserDelegateTask;
212→
213→/** Server relays a raw Claude NDJSON message to the browser. */
214→export interface ServerRelay {
215→  type: "relay";
216→  agentId: string;
217→  message: ClaudeMessage;
218→}
219→
220→/** Server notifies the browser of an agent status change. */
221→export interface ServerStatus {
222→  type: "status";
223→  agentId: string;
224→  status: AgentStatus;
225→}
226→
227→/** Server reports an error (e.g. no active session, process crash). */
228→export interface ServerError {
229→  type: "error";
230→  agentId: string;
231→  error: string;
232→}
233→
234→/** Summary of an agent for the sidebar. */
235→export interface AgentInfo {
236→  agentId: string;
237→  status: AgentStatus;
238→  tmuxSession: string | null;
239→  label: string;
240→  createdAt: number;
241→}
242→
243→/** Server sends the full list of agents after every state change. */
244→export interface ServerAgentList {
245→  type: "agent_list";
246→  agents: AgentInfo[];
247→}
248→
249→/** Server confirms a new agent was spawned and assigns its ID. */
250→export interface ServerSpawned {
251→  type: "spawned";
252→  agentId: string;
253→}
254→
255→/** Server sends full message history for an agent (in response to `request_history`). */
256→export interface ServerMessageHistory {
257→  type: "message_history";
258→  agentId: string;
259→  messages: ServerMessage[];
260→}
261→
262→/** CLI WebSocket disconnected (process may have crashed or exited). */
263→export interface ServerCliDisconnected {
264→  type: "cli_disconnected";
265→  agentId: string;
266→}
267→
268→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
269→export interface ServerCliConnected {
270→  type: "cli_connected";
271→  agentId: string;
272→}
273→
274→/** Server confirms message history was cleared for an agent. */
275→export interface ServerHistoryCleared {
276→  type: "history_cleared";
277→  agentId: string;
278→}
279→
280→/** Server sends the full task list to the browser. */
281→export interface ServerTaskList {
282→  type: "task_list";
283→  tasks: Task[];
