/**
 * Extract a stable dedup key from a relay message, if present.
 *
 * Claude NDJSON sends cumulative snapshots for two message types:
 * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
 * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
 *
 * Returns the key or null for non-deduplicable messages.
 */
function getRelayDedupKey(relayMsg: ServerMessage): string | null {
  if (relayMsg.type !== "relay") return null;
  const inner = relayMsg.message;
  if (inner.type === "assistant") {
    return (inner as { message?: { id?: string } }).message?.id ?? null;
  }
  if (inner.type === "user") {
    return (inner as { uuid?: string }).uuid ?? null;
  }
  return null;
}

/**
 * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 * Used both for live messages and for replaying message_history.
 *
 * When a relay message has a stable dedup key (assistant message.id or user uuid),
 * that key is used as the ChatMessage `id` so that cumulative snapshots produce
 * ChatMessages with the same identity — enabling in-place replacement.
 */
function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
  if (relayMsg.type === "relay") {
    const msg = relayMsg.message;
    const dedupKey = getRelayDedupKey(relayMsg);

    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
      const init = msg as ClaudeSystemInit;
      return {
        id: nextId(),
        role: "system",
        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "user") {
      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
      // Only render human-typed user messages (string content).
      // CLI tool_result messages have array content — these are internal
      // protocol messages and are only visible in the raw message viewer.
      if (typeof rawContent !== "string") return null;
      if (!rawContent.trim()) return null;
      return {
