/**
 * Find the index of an existing raw message that should be replaced by this relay.
 * Searches from the end for speed (cumulative snapshots arrive sequentially).
 */
function findLastRawIndex(rawMessages: ClaudeMessage[], relay: ServerMessage): number {
  if (relay.type !== "relay") return -1;
  const inner = relay.message;
  if (inner.type === "assistant") {
    const id = (inner as { message?: { id?: string } }).message?.id;
    if (!id) return -1;
    for (let i = rawMessages.length - 1; i >= 0; i--) {
      const r = rawMessages[i];
      if (r.type === "assistant" && (r as { message?: { id?: string } }).message?.id === id) return i;
    }
  }
  if (inner.type === "user") {
    const uuid = (inner as { uuid?: string }).uuid;
    if (!uuid) return -1;
    for (let i = rawMessages.length - 1; i >= 0; i--) {
      const r = rawMessages[i];
      if (r.type === "user" && (r as { uuid?: string }).uuid === uuid) return i;
    }
  }
  return -1;
}

